  ledId id0, 
  ledId id1 = ledId::none, 
  ledId id2 = ledId::none, 
  ledId id3 = ledId::none, 
  ledId id4 = ledId::none ); 参数 参数 类型 说明 id0 ledId LED ID： 0 – 红色 1 – 绿色 2 – 蓝色 3 – 白色 4 – 黄色 99 – 无 id1 ledId 第二个 LED 的索引（可选）。默认为 ledId::none 。 0 – 红色 1 – 绿色 2 – 蓝色 3 – 白色 4 – 黄色 99 – 无 id2 ledId 第三个 LED 的索引（可选）。默认为 ledId::none 。 0 – 红色 1 – 绿色 2 – 蓝色 3 – 白色 4 – 黄色 99 – 无 id3 ledId 第四个 LED 的索引（可选）。默认为 ledId::none 。 0 – 红色 1 – 绿色 2 – 蓝色 3 – 白色 4 – 黄色 99 – 无 id4 ledId 第五个 LED 的索引（可选）。默认为 ledId::none 。 0 – 红色 1 – 绿色 2 – 蓝色 3 – 白色 4 – 黄色 99 – 无 返回值 此函数无返回值。 disableBlink 通过 ID 禁用信号塔上多个 LED 的闪烁。 函数重载 void disableBlink( 
  ledId id0, 
  ledId id1 = ledId::none, 
  ledId id2 = ledId::none, 
  ledId id3 = ledId::none, 
  ledId id4 = ledId::none ); 参数 参数 类型 说明 id0 ledId 第一个 LED 的索引。 0 – 红色 1 – 绿色 2 – 蓝色 3 – 白色 4 – 黄色 99 – 无 id1 ledId 第二个 LED 的索引（可选）。默认为 ledId::none 。 0 – 红色 1 – 绿色 2 – 蓝色 3 – 白色 4 – 黄色 99 – 无 id2 ledId 第三个 LED 的索引（可选）。默认为 ledId::none 。 0 – 红色 1 – 绿色 2 – 蓝色 3 – 白色 4 – 黄色 99 – 无 id3 ledId 第四个 LED 的索引（可选）。默认为 ledId::none 。 0 – 红色 1 – 绿色 2 – 蓝色 3 – 白色 4 – 黄色 99 – 无 id4 ledId 第五个 LED 的索引（可选）。默认为 ledId::none 。 0 – 红色 1 – 绿色 2 – 蓝色 3 – 白色 4 – 黄色 99 – 无 返回值 此函数无返回值。 pressing 返回信号塔的保险杠当前是否被按下。这可以用作紧急停止。 函数重载 bool pressing(); 参数 该函数没有参数。 返回值 返回一个布尔值，指示信号塔的保险杠当前是否被按下。 true — 信号塔的保险杠当前正在被按下。 false — 信号塔的保险杠没有被按下。 pressed 注册一个在按下信号塔保险杠时调用的函数。 函数重载 void pressed( void (* callback)(void) ); 参数 参数 类型 说明 callback void (*)(void) 指向按下保险杠时将调用的函数的指针。 返回值 此函数无返回值。 示例 定义回调函数（在 int main() 之外） // Display a message when bumper is pressed
void towerBumperPressed() {
  Brain.Screen.print("tower bumper pressed");
} 在 int main() 内部注册回调函数 int main() {
  /* vexcodeInit() is only required when using VEXcode.
  Remove vexcodeInit() if compiling in VS Code. */
  vexcodeInit();

  // Run towerBumperPressed when the tower bumper 
  // is pressed
  SignalTower.pressed(towerBumperPressed);
} released 注册一个在信号塔缓冲器释放时调用的函数。 函数重载 void released( void (* callback)(void) ); 参数 参数 类型 说明 callback void (*)(void) 指向释放保险杠时将调用的函数的指针。 返回值 此函数无返回值。 示例 定义回调函数（在 int main() 之外） // Display a message when bumper is released
void towerBumperReleased() {
  Brain.Screen.print("tower bumper released");
} 在 int main() 内部注册回调函数 int main() {
  /* vexcodeInit() is only required when using VEXcode.
  Remove vexcodeInit() if compiling in VS Code. */
  vexcodeInit();

  // Run towerBumperReleased when the tower bumper 
  // is released
  SignalTower.released(towerBumperReleased);
}

