  }
  else {
    Drivetrain.stop();
  }

  wait(20, msec);
} 回调函数 changed 当操纵杆的位置沿该轴变化时， changed 运行一个函数。 函数签名 void changed(void (* callback)(void)) const; 参数 类型 说明 callback void (*)(void) 每次操纵杆位置沿该轴发生变化时运行的函数。 返回值 此函数无返回值。 示例 在 main 外部定义回调函数。 // Rumble when the left joystick moves
void controllerRumble() {
  Controller.rumble(".");
} 在 main 内部注册回调函数。 int main() {
  vexcodeInit();

  // Run controllerRumble when the joystick's position changes along Axis4
  Controller.Axis4.changed(controllerRumble);
}

