  // Begin project code
  thread blinkScreenThread = thread(blinkScreen);
  thread turningThread = thread(turning);
} 成员函数 线程类包括以下成员函数： interrupt – 手动停止线程，对于停止后台行为很有用。 interrupt 手动停止线程，这在不再需要任务或程序需要重置线程时很有用。 函数重载 void interrupt(); 参数 该函数没有参数。 返回值 此函数无返回值。 说明与注意事项 线程一旦停止，就无法重新启动。要再次运行它，您必须使用 thread 创建一个新线程。 当不再需要任务或程序需要重置或重新分配线程时，这很有用。 示例 定义函数（在 int main() 之外） // Loop through red and green
void colorLoop() {
  while (true) {
    Brain.Screen.drawRectangle(0, 120, 480, 120, red);
    wait(0.5, seconds);
    Brain.Screen.drawRectangle(0, 120, 480, 120, green);
