  if (n > 0 && strcmp(msg, "pressed") == 0) {
    Brain.Screen.newLine();
    Brain.Screen.print("Manager is being pressed!");
  }
  wait(0.05, seconds);
} receive 从链接连接接收消息。 函数重载 int32_t receive(
  char     *buffer,
  int32_t   length, 
  int32_t   timeoutMs = 500 ); 参数 参数 类型 说明 buffer char* 用于存储接收到的消息的缓冲区。 length int32_t 缓冲区的长度。 timeoutMs int32_t 仅当队列为空时， receive 将等待新消息的时间（以毫秒为单位）。默认值为 300,000（300 秒）。 返回值 该函数返回接收到的字节数。 说明与注意事项 receive 从另一个链接的 V5 主控器返回下一条排队消息。消息按 FIFO 顺序读取（最旧的未读优先）。如果调用 receive 时队列为空，则它将等待指定的 timeout 来接收新消息。如果该窗口中没有消息到达，则 receive 返回 0 ，之后发送的任何消息都会保留在队列中，以便下次使用 receive 时读取。 如果其他链接的 V5 主控器仅发送 string ，则 receive 返回该确切字符串。 如果另一个链接的 V5 主控器发送了整数和/或浮点数，则 receive 返回一个编码字符串，该字符串按以下顺序组合所有字段： .string_integer_float 例如，如果另一个链接的 V5 主控器使用 link.send("string", 1, 2.55) ，则使用 link.receive() 返回编码字符串，例如 .string_1_2.5500 。您可以拆分此编码字符串（请参阅下面的示例）以提取消息名称、整数和浮点值。 如果您不想手动拆分/解析，请使用 received 为特定消息名称注册处理程序；处理程序接收发送的值作为参数。 示例 使用 link.send("string", 1, 2.55) 被接收为 .string_1_2.5500 。 机器人 1 的代码 // Tell the other robot when the screen is being pressed

// Create the link
message_link link = message_link(PORT1, "VEXRoboticsLink123456789", linkType::manager, true);

// Do not run code UNTIL the Brains are linked
